// Monta o plano de convites de moderador do dia.
// Espelha .claude/skills/convites-moderador/config.json (estado 2026-08-19).
// Editar SERIES aqui = editar quem recebe convite. Saida: 1 item por (sessao, email).
// Convites SO em dias uteis (decisao Victor 2026-07-13): a recorrencia do ClickMeeting
// nao pula fim de semana, entao sab/dom a sessao roda sem vendedor de proposito —
// as LPs continuam aceitando inscricao normalmente.
const SERIES = {
  '17727': { label: 'Buzzcreators (09:40 BRT)',                           lang: 'br', emails: ['gabriel.leal@buzzmonitor.com.br', 'lucas.campos@buzzmonitor.com.br'] },
  '17927': { label: 'Buzzmonitor Tu primer listening en 5 pasos (LATAM)', lang: 'es', emails: ['milagro.pantoja@buzzmonitor.com', 'daniel.topete@buzzmonitor.com'] },
  '17646': { label: 'Buzzmonitor Que es MCP (LATAM)',                     lang: 'es', emails: ['milagro.pantoja@buzzmonitor.com', 'daniel.topete@buzzmonitor.com'] },
  '17701': { label: 'Buzzmonitor Atencion al Cliente (LATAM)',            lang: 'es', emails: ['milagro.pantoja@buzzmonitor.com', 'daniel.topete@buzzmonitor.com'] },
  '17928': { label: 'Buzzmonitor Caso Smart Fit (LATAM)',                 lang: 'es', emails: ['milagro.pantoja@buzzmonitor.com', 'daniel.topete@buzzmonitor.com'] },
  '17929': { label: 'Cxpress Por que bloquean tu WhatsApp (LATAM)',       lang: 'es', emails: ['laura.leon@cxpress.ai', 'milagro.pantoja@buzzmonitor.com', 'daniel.topete@buzzmonitor.com'] },
};
// 2026-08-19: sairam 17689 (Conheca a Cxpress) e 17671 (Cxpress Vozxpress) — series apagadas
// no ClickMeeting por limite de disco, com zero inscritos. Entraram 17927, 17928 e 17929.
// Espelho de .claude/skills/convites-moderador/config.json — manter os dois em sincronia.

const TZ_PADRAO = 'America/Sao_Paulo';
function isWeekend(date, tz) {
  const w = new Intl.DateTimeFormat('en-US', { weekday: 'short', timeZone: tz || TZ_PADRAO }).format(date);
  return w === 'Sat' || w === 'Sun';
}

// Trava de fim de semana: sab/dom nao envia convite nenhum.
if (isWeekend(new Date(), TZ_PADRAO)) {
  console.log('SKIP TOTAL: fim de semana (America/Sao_Paulo) — convites so em dias uteis.');
  return [];
}

// Junta as conferencias ativas (a GET pode vir como array bruto, {data:[...]} ou ja dividida em itens).
const confs = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) confs.push(...j);
  else if (j && Array.isArray(j.data)) confs.push(...j.data);
  else if (j && (j.id || j.recurring_config_id)) confs.push(j);
}

const now = Date.now();
function nextSession(rid) {
  let best = null;
  for (const c of confs) {
    if (!c || !c.starts_at) continue;
    if (String(c.recurring_config_id == null ? '' : c.recurring_config_id) !== String(rid)) continue;
    if (c.registration_enabled !== 1 && c.registration_enabled !== true) continue; // so sessoes com registro aberto
    const t = new Date(c.starts_at).getTime();
    if (!Number.isFinite(t) || t <= now) continue;                                 // so futuro
    if (isWeekend(new Date(t), c.timezone)) continue;                              // nunca convida pra sessao de sab/dom
    if (best === null || t < best.t) best = { t, c };                              // a mais proxima
  }
  return best ? best.c : null;
}

const out = [];
const skips = [];
for (const [rid, cfg] of Object.entries(SERIES)) {
  const session = nextSession(rid);
  if (!session) { skips.push(cfg.label + ' (' + rid + ')'); continue; }
  for (const email of cfg.emails) {
    out.push({ json: {
      recurringConfigId: rid,
      label: cfg.label,
      roomId: session.id,
      startsAt: session.starts_at,
      lang: cfg.lang,
      email: email,
    }});
  }
}
if (skips.length) console.log('SKIP (sem sessao futura ativa em dia util): ' + skips.join(' | '));
if (out.length === 0) console.log('Nenhuma sessao futura hoje — nada a enviar.');
return out;
